def build_model(config: dict) -> nn.Module:
    """Returns the training model; config['model_kwargs'] overrides constructor kwargs."""
    kwargs = dict(config.get("model_kwargs", {}))
    data = _types.SimpleNamespace(Dictionary=Dictionary, Corpus=Corpus)
    corpus = data.Corpus('./data/wikitext-2')
    ntokens = len(corpus.dictionary)
    model = RNNModel('LSTM', ntokens, 200, 200, 2, 0.2, False, **kwargs)
